import { useState } from 'react'
import { Avatar, AvatarFallback } from '@kitora/ui/avatar'
import { Badge } from '@kitora/ui/badge'
import { Button } from '@kitora/ui/button'
import { Tabs, TabsList, TabsTrigger } from '@kitora/ui/tabs'
import { SearchInput } from '@kitora/ui/search-input'
import { cn } from '@kitora/ui/utils'
import { channels, folders, seedMessages } from './data'
import { MessageView } from './message-view'

/** A three-pane mail client: folders and labels, a message list with Focused and Other tabs, and the open message with a reply box. */
export function InboxTemplate() {
  const [active, setActive] = useState(seedMessages[0]?.id ?? null)
  const [folder, setFolder] = useState('inbox')
  const [tab, setTab] = useState('focused')
  const selected = seedMessages.find((m) => m.id === active) ?? null

  return (
    <div className="grid h-[calc(100dvh-3.5rem)] w-full lg:grid-cols-[200px_320px_1fr]">
      {/* Sidebar */}
      <aside className="hidden border-r border-border bg-surface-1 lg:block">
        <div className="px-3 py-3">
          <Button size="sm" className="w-full">
            <Mail />
            New message
          </Button>
        </div>
        <nav className="px-2 text-sm">
          <ul className="space-y-px">
            {folders.map((f) => {
              const Icon = f.icon
              const active_ = folder === f.id
              return (
                <li key={f.id}>
                  <button
                    onClick={() => setFolder(f.id)}
                    className={cn(
                      'flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left transition-colors',
                      active_
                        ? 'bg-muted text-foreground'
                        : 'text-muted-foreground hover:bg-muted/60 hover:text-foreground',
                    )}
                  >
                    <Icon className="size-3.5" />
                    <span className="flex-1">{f.label}</span>
                    {f.count ? (
                      <span className="font-mono text-[10px] text-muted-foreground">
                        {f.count}
                      </span>
                    ) : null}
                  </button>
                </li>
              )
            })}
          </ul>
          <div className="mt-5 px-2">
            <h3 className="mb-1.5 font-mono text-[10px] uppercase tracking-wider text-muted-foreground">
              Channels
            </h3>
            <ul className="space-y-px">
              {channels.map((c) => (
                <li key={c.id}>
                  <button className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground">
                    <Hash className="size-3.5" />
                    <span className="flex-1">{c.label}</span>
                    {c.count ? (
                      <span className="font-mono text-[10px] text-muted-foreground">
                        {c.count}
                      </span>
                    ) : null}
                  </button>
                </li>
              ))}
            </ul>
          </div>
        </nav>
      </aside>

      {/* List */}
      <section className="flex min-h-0 flex-col border-r border-border">
        <div className="border-b border-border px-4 py-3">
          <div className="flex items-center justify-between gap-2">
            <h2 className="text-sm font-semibold tracking-tight">Inbox</h2>
            <Badge variant="outline" className="font-mono text-[10px]">
              {seedMessages.filter((m) => m.unread).length} unread
            </Badge>
          </div>
          <div className="mt-2.5">
            <SearchInput placeholder="Search inbox…" containerClassName="w-full" />
          </div>
          <Tabs value={tab} onValueChange={setTab} className="mt-2.5">
            <TabsList className="w-full">
              <TabsTrigger value="focused" className="flex-1">
                Focused
              </TabsTrigger>
              <TabsTrigger value="other" className="flex-1">
                Other
              </TabsTrigger>
            </TabsList>
          </Tabs>
        </div>
        <ul className="flex-1 overflow-y-auto">
          {seedMessages.map((m) => (
            <li key={m.id}>
              <button
                onClick={() => setActive(m.id)}
                className={cn(
                  'flex w-full items-start gap-3 border-b border-border/60 px-4 py-3 text-left transition-colors',
                  m.id === active ? 'bg-accent' : 'hover:bg-muted/40',
                )}
              >
                <Avatar className="size-7 shrink-0">
                  <AvatarFallback className="text-[10px]">
                    {m.from.name.split(' ').map((n) => n[0]).join('')}
                  </AvatarFallback>
                </Avatar>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5">
                    <span
                      className={cn(
                        'truncate text-[13px]',
                        m.unread ? 'font-semibold text-foreground' : 'text-foreground',
                      )}
                    >
                      {m.from.name}
                    </span>
                    {m.thread ? (
                      <span className="rounded bg-muted px-1 py-0.5 font-mono text-[9px] text-muted-foreground">
                        {m.thread}
                      </span>
                    ) : null}
                    <span className="ml-auto shrink-0 font-mono text-[10px] text-muted-foreground">
                      {m.receivedAt}
                    </span>
                  </div>
                  <p
                    className={cn(
                      'mt-0.5 truncate text-[12px]',
                      m.unread ? 'font-medium text-foreground' : 'text-muted-foreground',
                    )}
                  >
                    {m.subject}
                  </p>
                  <p className="mt-0.5 line-clamp-1 text-[11px] text-muted-foreground">
                    {m.preview}
                  </p>
                  {m.labels?.length || m.starred || m.unread ? (
                    <div className="mt-1.5 flex items-center gap-1">
                      {m.labels?.map((l) => (
                        <span
                          key={l}
                          className="inline-flex items-center rounded-sm border border-border bg-background px-1.5 py-0.5 text-[9px] font-medium uppercase tracking-wider text-muted-foreground"
                        >
                          {l}
                        </span>
                      ))}
                      {m.starred ? (
                        <Star className="size-3 text-amber-500" />
                      ) : null}
                      {m.unread ? (
                        <span className="ml-auto size-1.5 rounded-full bg-primary" />
                      ) : null}
                    </div>
                  ) : null}
                </div>
              </button>
            </li>
          ))}
        </ul>
      </section>

      {/* Detail */}
      <section className="flex min-h-0 flex-col bg-background">
        {selected ? <MessageView message={selected} /> : <Empty />}
      </section>
    </div>
  )
}

function Empty() {
  return (
    <div className="grid h-full place-items-center">
      <div className="flex flex-col items-center gap-3 text-center">
        <div className="grid size-12 place-items-center rounded-full border border-dashed border-border-strong text-muted-foreground">
          <Mail className="size-5" />
        </div>
        <div>
          <p className="text-sm font-medium">Pick a message</p>
          <p className="mt-1 text-xs text-muted-foreground">
            Or hit ⌘N to compose a new one.
          </p>
        </div>
      </div>
    </div>
  )
}
